) (*strategy.CheckpointInfo, error) {
	if settings.MirrorsToV1CustomRef(ctx) {
		return nil, storeErr
	}
	return readCheckpointInfoFromMetadataBranch(ctx, repo, checkpointID, storeErr)
}

